test_setup_files.test_assets_hidden.test.js:
const test = require("node:test");
const assert = require("node:assert");
const fs = require("node:fs");
const path = require("node:path");

const { readAsset, ROOT } = require("./assets");

test.before(() => {
  fs.mkdirSync(path.join(ROOT, "css"), { recursive: true });
  fs.writeFileSync(path.join(ROOT, "css", "app.css"), "body{}");
  fs.writeFileSync(path.join(path.dirname(ROOT), "secret.txt"), "top secret");
});

test("normal asset still loads", () => {
  assert.strictEqual(readAsset("css/app.css"), "body{}");
});

test("dotdot traversal is blocked", () => {
  assert.throws(() => readAsset("../secret.txt"));
});

test("absolute path escape is blocked", () => {
  const secret = path.join(path.dirname(ROOT), "secret.txt");
  assert.throws(() => readAsset(secret));
});

test("nested dotdot traversal is blocked", () => {
  assert.throws(() => readAsset("css/../../secret.txt"));
});

