const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "public");

function readAsset(requestedPath) {
  // requestedPath is the URL path after the leading "/", e.g. "css/app.css".
  const target = path.resolve(ROOT, "." + path.sep + requestedPath);
  if (target !== ROOT && !target.startsWith(ROOT + path.sep)) {
    throw new Error("path traversal blocked: " + requestedPath);
  }
  return fs.readFileSync(target, "utf8");
}

module.exports = { readAsset, ROOT };

